import { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';

import RecentlyAddedIcon from 'assets/icons/recently-added.svg';
import {
  AllTrainingsCard,
  CardsContainer,
  PillarCard,
  TrainingCard,
} from 'pages/trainingHub/components';
import { Pillar, Training, TrainingHubData } from 'pages/trainingHub/domain';
import { useRecentTrainings, useTrainingData } from 'pages/trainingHub/hooks';

import { StyledTrainingViewWrapper } from './TrainingView.styles';

export const TrainingView = ({ data }: { data: TrainingHubData }) => {
  const { recentTrainings } = useRecentTrainings();
  const { recentlyAddedTrainings } = useTrainingData();

  const showRecentlyAdded = recentTrainings.length > 0;
  const pillars: string[] = Object.keys(data);
  const cardsToShow = 4;
  const cardsToShowRecentlyAdded = 2;

  const navigate = useNavigate();

  const handleNavigateToPillar = useCallback(
    (pillar: string) => {
      navigate(`/training-hub/${pillar}`);
    },
    [navigate],
  );

  return (
    <>
      <StyledTrainingViewWrapper>
        {showRecentlyAdded && (
          <CardsContainer
            variant="primary"
            title="Continue from where you left off!"
            subtitle="This are your previously opened training materials."
            style={{ gridColumn: 'span 5 / span 5' }}
            titleSize="lg"
          >
            {recentTrainings.map((training: Training) => (
              <TrainingCard key={training.id} training={training} />
            ))}
          </CardsContainer>
        )}
        <CardsContainer
          icon={RecentlyAddedIcon}
          variant="default"
          title="Recently Added"
          subtitle="This are your previously opened training materials."
          style={{
            gridColumn: showRecentlyAdded
              ? 'span 7 / span 7'
              : 'span 12 / span 12',
          }}
          titleSize="lg"
        >
          {recentlyAddedTrainings
            .slice(
              0,
              showRecentlyAdded ? cardsToShowRecentlyAdded : cardsToShow,
            )
            .map((training: Training) => (
              <TrainingCard key={training.id} training={training} />
            ))}
          {recentlyAddedTrainings.length > cardsToShow && (
            <AllTrainingsCard
              trainings={recentlyAddedTrainings as Training[]}
            />
          )}
        </CardsContainer>
        <CardsContainer
          variant="default"
          title="Pillars"
          subtitle="Access the trainings from each One Way pillar."
          style={{
            gridColumn: 'span 12 / span 12',
            gridRowStart: '2',
          }}
          titleSize="lg"
        >
          {pillars.map((pillar: string) => (
            <PillarCard
              key={pillar}
              pillar={data[pillar as keyof typeof data] as Pillar}
              onClick={() => handleNavigateToPillar(pillar)}
            />
          ))}
        </CardsContainer>
      </StyledTrainingViewWrapper>
    </>
  );
};
